// INTERVIEW QUESTION:
// Write a strongly typed 'groupBy' function.

// BAD (The JS way):
// function groupBy(arr, key) { ... }

// EXCELLENT (The TS way):
// 1. T is the object inside the array
// 2. K is the specific key we want to group by (Must be a key of T)
function groupBy<T, K extends keyof T>(
  array: T[], 
  key: K
): Record<string, T[]> {  // Return type is a dictionary where values are arrays of T

  return array.reduce((accumulator, item) => {
    // We cast to string because object keys must be strings/symbols
    const groupValue = String(item[key]); 

    if (!accumulator[groupValue]) {
      accumulator[groupValue] = [];
    }

    accumulator[groupValue].push(item);
    return accumulator;
  }, {} as Record<string, T[]>);
}

const users = [
  { role: 'admin', name: 'Alice' },
  { role: 'user', name: 'Bob' },
  { role: 'admin', name: 'Charlie' }
];

const grouped = groupBy(users, 'role');
// TS knows exactly what 'grouped' looks like!
console.log(grouped.admin.length); // 2
